/**
 * The graphql function is used to parse GraphQL queries into a document that can be used by GraphQL clients.
 */
export function graphql(source: "query Search($query: String!, $first: Int) {\n  search(query: $query, scopes: [NOTES, TOPICS], first: $first) {\n    notes {\n      snippet\n      note {\n        id\n        title\n        visibility\n        viewerAccess\n        publishedAt\n        owner {\n          id\n          displayName\n        }\n      }\n    }\n    topics {\n      id\n      title\n      subject {\n        id\n        title\n      }\n    }\n  }\n}"): (typeof documents)["query Search($query: String!, $first: Int) {\n  search(query: $query, scopes: [NOTES, TOPICS], first: $first) {\n    notes {\n      snippet\n      note {\n        id\n        title\n        visibility\n        viewerAccess\n        publishedAt\n        owner {\n          id\n          displayName\n        }\n      }\n    }\n    topics {\n      id\n      title\n      subject {\n        id\n        title\n      }\n    }\n  }\n}"];

export function graphql(source: string) {
  return (documents as any)[source] ?? {};
}

export type DocumentType<TDocumentNode extends DocumentNode<any, any>> = TDocumentNode extends DocumentNode<  infer TType,  any>  ? TType  : never;